B=[
('الرِّحْلَةُ السَّادِسَةُ: الْجَبَلُ الْعَظِيمُ','Altıncı yolculuk: Büyük dağ',[
('فِي الْيَوْمِ التَّالِي قَالَ السِّنْدِبَادُ لِلْحَمَّالِ: «اسْمَعْ يَا أَخِي.»','Ertesi gün Sindbad hamala dedi ki: “Dinle kardeşim.”'),
('«كُنْتُ جَالِسًا فِي بَيْتِي، فَمَرَّ بِي تُجَّارٌ رَاجِعُونَ مِنَ السَّفَرِ.»','“Evimde oturuyordum; yolculuktan dönen tüccarlar yanımdan geçti.”'),
('«فَتَذَكَّرْتُ الْبَحْرَ، وَاشْتَقْتُ إِلَيْهِ.»','“Denizi hatırladım ve onu özledim.”'),
('«فَاشْتَرَيْتُ بَضَائِعَ، وَرَكِبْتُ سَفِينَةً كَبِيرَةً.»','“Mallar satın aldım ve büyük bir gemiye bindim.”'),
('«وَفِي يَوْمٍ صَرَخَ الرُّبَّانُ، وَرَمَى عِمَامَتَهُ، وَبَكَى.»','“Bir gün kaptan bağırdı, sarığını attı ve ağladı.”'),
('«قَالَ: ضَلَلْنَا الطَّرِيقَ، وَالرِّيحُ تَدْفَعُنَا إِلَى جَبَلٍ عَظِيمٍ!»','“Dedi ki: Yolumuzu kaybettik; rüzgâr bizi büyük bir dağa itiyor!”'),
('«فَضَرَبَتِ السَّفِينَةُ الْجَبَلَ، وَتَكَسَّرَتْ أَلْوَاحُهَا.»','“Gemi dağa çarptı ve tahtaları parçalandı.”')]),
('شَاطِئُ الْجَوَاهِرِ','Mücevher kıyısı',[
('«نَزَلْنَا إِلَى الشَّاطِئِ، فَرَأَيْنَا عَجَبًا.»','“Kıyıya indik ve şaşılacak bir şey gördük.”'),
('«كَانَتِ الْأَرْضُ مَمْلُوءَةً بِالْيَاقُوتِ وَالْجَوَاهِرِ.»','“Toprak yakut ve mücevherlerle doluydu.”'),
('«وَكَانَتْ هُنَاكَ أَخْشَابٌ وَبَضَائِعُ مِنْ سُفُنٍ كَثِيرَةٍ غَرِقَتْ قَبْلَنَا.»','“Orada bizden önce batmış birçok gemiden kalma tahtalar ve mallar vardı.”'),
('«لَكِنْ لَمْ يَكُنْ هُنَاكَ طَعَامٌ كَثِيرٌ.»','“Ama orada çok yiyecek yoktu.”'),
('«فَقَسَمْنَا الطَّعَامَ بَيْنَنَا قَلِيلًا قَلِيلًا.»','“Yiyeceği aramızda azar azar paylaştırdık.”'),
('«وَكَانَ أَصْحَابِي يَمُوتُونَ وَاحِدًا بَعْدَ وَاحِدٍ، فَنَدْفِنُهُمْ.»','“Arkadaşlarım birer birer ölüyordu; onları gömüyorduk.”'),
('«حَتَّى بَقِيتُ وَحْدِي.»','“Sonunda yalnız kaldım.”'),
('«فَحَفَرْتُ قَبْرًا لِنَفْسِي، وَقُلْتُ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ.»','“Kendime bir mezar kazdım ve dedim ki: Güç ve kuvvet ancak Allah’tandır.”')]),
('النَّهْرُ تَحْتَ الْجَبَلِ','Dağın altındaki ırmak',[
('«ثُمَّ رَأَيْتُ نَهْرًا يَدْخُلُ فِي الْجَبَلِ، فِي مَغَارَةٍ مُظْلِمَةٍ.»','“Sonra karanlık bir mağarada dağın içine giren bir ırmak gördüm.”'),
('«فَفَكَّرْتُ: هَذَا النَّهْرُ يَخْرُجُ فِي مَكَانٍ آخَرَ.»','“Düşündüm: Bu ırmak başka bir yerden çıkar.”'),
('«إِنْ عِشْتُ وَصَلْتُ، وَإِنْ مِتُّ فَالْمَوْتُ هُنَا أَيْضًا.»','“Yaşarsam varırım; ölürsem, ölüm burada da var.”'),
('«فَصَنَعْتُ فُلْكًا صَغِيرًا مِنَ الْأَخْشَابِ وَالْحِبَالِ.»','“Tahtalardan ve iplerden küçük bir sal yaptım.”'),
('«وَوَضَعْتُ عَلَيْهِ الْيَاقُوتَ وَالْجَوَاهِرَ وَقَلِيلًا مِنَ الطَّعَامِ.»','“Üzerine yakutları, mücevherleri ve biraz yiyecek koydum.”'),
('«ثُمَّ رَكِبْتُهُ، وَدَخَلْتُ الْمَغَارَةَ مَعَ الْمَاءِ.»','“Sonra ona bindim ve suyla birlikte mağaraya girdim.”'),
('«كَانَ الظَّلَامُ شَدِيدًا، وَالْمَاءُ يَجْرِي بِسُرْعَةٍ.»','“Karanlık çok koyuydu ve su hızla akıyordu.”'),
('«فَتَعِبْتُ وَنِمْتُ عَلَى الْفُلْكِ.»','“Yoruldum ve salın üzerinde uyudum.”')]),
('أَرْضُ سَرَنْدِيبَ','Serendib ülkesi',[
('«فَلَمَّا اسْتَيْقَظْتُ رَأَيْتُ النُّورَ، وَرِجَالًا حَوْلِي.»','“Uyandığımda ışığı ve etrafımda adamlar gördüm.”'),
('«كَانَ الْفُلْكُ مَرْبُوطًا عِنْدَ شَاطِئِ النَّهْرِ.»','“Sal ırmağın kıyısına bağlanmıştı.”'),
('«سَأَلُونِي بِلُغَتِهِمْ، فَلَمْ أَفْهَمْ.»','“Bana kendi dillerinde sordular; anlamadım.”'),
('«ثُمَّ جَاءَ رَجُلٌ يَتَكَلَّمُ الْعَرَبِيَّةَ، فَقَالَ: السَّلَامُ عَلَيْكُمْ، مَنْ أَنْتَ؟»','“Sonra Arapça konuşan bir adam geldi ve dedi ki: Selâmün aleyküm, sen kimsin?”'),
('«فَحَكَيْتُ لَهُ قِصَّتِي، فَتَعَجَّبَ.»','“Ona hikâyemi anlattım; şaştı.”'),
('«قَالَ: هَذِهِ أَرْضُ سَرَنْدِيبَ، وَيَجِبُ أَنْ تَذْهَبَ مَعَنَا إِلَى الْمَلِكِ.»','“Dedi ki: Burası Serendib ülkesi; bizimle krala gitmelisin.”'),
('«فَأَعْطَوْنِي فَرَسًا، وَمَشَوْا مَعِي إِلَى الْمَدِينَةِ.»','“Bana bir at verdiler ve benimle şehre yürüdüler.”')]),
('مَلِكُ سَرَنْدِيبَ','Serendib kralı',[
('«كَانَ الْمَلِكُ جَالِسًا عَلَى سَرِيرٍ مِنْ ذَهَبٍ، وَحَوْلَهُ الْفِيَلَةُ وَالْحُرَّاسُ.»','“Kral altından bir tahtta oturuyordu; etrafında filler ve muhafızlar vardı.”'),
('«سَلَّمْتُ عَلَيْهِ، وَحَكَيْتُ لَهُ رِحْلَتِي.»','“Ona selam verdim ve yolculuğumu anlattım.”'),
('«قَالَ الْمَلِكُ: عَجِيبٌ! اكْتُبُوا قِصَّتَهُ بِمَاءِ الذَّهَبِ.»','“Kral dedi ki: Şaşılacak şey! Hikâyesini altın suyuyla yazın.”'),
('«ثُمَّ قَدَّمْتُ لَهُ مِنَ الْيَاقُوتِ، فَقَالَ: لَا آخُذُ مِنْ مَالِكَ شَيْئًا، بَلْ أَزِيدُكَ.»','“Sonra ona yakutlardan sundum; dedi ki: Malından hiçbir şey almam, aksine sana daha fazlasını veririm.”'),
('«وَسَأَلَنِي عَنْ بَغْدَادَ وَعَنِ الْخَلِيفَةِ هَارُونَ الرَّشِيدِ.»','“Bana Bağdat’ı ve Halife Hârûnürreşîd’i sordu.”'),
('«فَقُلْتُ: هُوَ خَلِيفَةٌ عَادِلٌ، يُحِبُّ الْعِلْمَ وَالْعُلَمَاءَ.»','“Dedim ki: O âdil bir halifedir; ilmi ve âlimleri sever.”'),
('«قَالَ الْمَلِكُ: أُحِبُّ أَنْ أُرْسِلَ إِلَيْهِ هَدِيَّةً مَعَكَ.»','“Kral dedi ki: Seninle ona bir hediye göndermek isterim.”')]),
('الْهَدِيَّةُ وَالْعَوْدَةُ','Hediye ve dönüş',[
('«أَعْطَانِي الْمَلِكُ كَأْسًا مِنَ الْيَاقُوتِ، وَفِرَاشًا مِنْ جِلْدِ حَيَّةٍ عَجِيبَةٍ.»','“Kral bana yakuttan bir kadeh ve şaşılacak bir yılanın derisinden bir döşek verdi.”'),
('«وَأَعْطَانِي عُودًا وَمِسْكًا، وَجَارِيَةً تَخْدُمُ الْخَلِيفَةَ.»','“Bana öd ağacı, misk ve halifeye hizmet edecek bir cariye verdi.”'),
('«وَكَتَبَ رِسَالَةً إِلَى الْخَلِيفَةِ فِيهَا سَلَامٌ وَمَحَبَّةٌ.»','“Halifeye içinde selam ve sevgi olan bir mektup yazdı.”'),
('«فَرَكِبْتُ سَفِينَةً، وَوَصَلْتُ إِلَى بَغْدَادَ سَالِمًا.»','“Bir gemiye bindim ve Bağdat’a sağ salim vardım.”'),
('«وَذَهَبْتُ إِلَى قَصْرِ الْخَلِيفَةِ، وَقَدَّمْتُ لَهُ الْهَدِيَّةَ وَالرِّسَالَةَ.»','“Halifenin sarayına gittim ve ona hediyeyi ve mektubu sundum.”'),
('«فَفَرِحَ الْخَلِيفَةُ، وَأَكْرَمَنِي.»','“Halife sevindi ve bana ikramda bulundu.”'),
('قَالَ الْحَمَّالُ: «حَمَّالٌ مِثْلِي يَجْلِسُ مَعَ مَنْ رَأَى الْخَلِيفَةَ!»','Hamal dedi ki: “Benim gibi bir hamal, halifeyi görmüş biriyle oturuyor!”'),
('قَالَ السِّنْدِبَادُ: «كُلُّنَا عِبَادُ اللّٰهِ. وَغَدًا أَحْكِي لَكَ الرِّحْلَةَ الْأَخِيرَةَ.»','Sindbad dedi ki: “Hepimiz Allah’ın kullarıyız. Yarın sana son yolculuğu anlatırım.”')]),
]
